<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { api } from '../api/client'
import type { ComponentDescriptor, ComposerStage, ProfileComposerCatalog, ProfileComposerPreflightResponse } from '../api/contracts'
import { useProfileDraft } from '../composables/useProfileDraft'
const { draft, resetDraft, updateStage, toggleChecker, moveChecker } = useProfileDraft()
const catalog = ref<ProfileComposerCatalog | null>(null), result = ref<ProfileComposerPreflightResponse | null>(null), error = ref(''), loading = ref(true), checking = ref(false)
const stage = (name: ComposerStage): ComponentDescriptor[] => catalog.value?.stages[name] || []
const descriptor = (name: ComposerStage, id: string) => stage(name).find(item => item.id === id)
const selectedCheckers = computed(() => draft.checkers.map(item => descriptor('checker', item)).filter(Boolean) as ComponentDescriptor[])
const risks = (item?: ComponentDescriptor) => item ? Object.entries(item.capabilities).filter(([, allowed]) => allowed).map(([name]) => name).join(' · ') || '离线本地' : ''
async function preflight() { checking.value = true; error.value = ''; try { result.value = await api.preflightProfileDraft(draft); if (!result.value.valid) error.value = '预检发现需要修复的组合或权限问题。' } catch (e) { error.value = e instanceof Error ? e.message : 'Profile 预检失败' } finally { checking.value = false } }
watch(draft, () => { result.value = null; error.value = '' }, { deep: true })
onMounted(async () => { try { catalog.value = (await api.profileComposerCatalog()).catalog } catch (e) { error.value = e instanceof Error ? e.message : '无法读取组件目录' } finally { loading.value = false } })
</script>
<template><section class="page composer"><div class="page-heading"><div><p class="eyebrow">PROFILE DRAFT → PURE PREFLIGHT</p><h1>Profile 下拉编排</h1><p>按固定链路选择组件并生成完整 Profile 草稿。预检只检查规则：不会保存、执行、联网、调用模型或读取队列。</p></div><RouterLink class="quiet-button" to="/profile-composer/canvas">切换到画布编排</RouterLink></div><p v-if="error" class="data-warning">⚠ {{ error }}</p><p v-if="loading" class="empty-state">正在读取服务端组件目录…</p><template v-else-if="catalog"><section class="workspace-panel composer-meta"><label>Profile ID<input v-model="draft.id" maxlength="64" /></label><label>版本<input v-model.number="draft.version" type="number" min="1" /></label><label class="wide">说明<textarea v-model="draft.description" rows="2" /></label></section><section class="composer-flow"><article><header><b>1. Source</b><span>需求来源</span></header><select :value="draft.source.name" @change="updateStage('source', ($event.target as HTMLSelectElement).value)"><option v-for="item in stage('source')" :key="item.id" :value="item.id">{{ item.label }}</option></select><p>{{ descriptor('source', draft.source.name)?.description }}</p></article><i>→</i><article><header><b>2. Compiler</b><span>需求转 Spec</span></header><select :value="draft.compiler" @change="updateStage('compiler', ($event.target as HTMLSelectElement).value)"><option v-for="item in stage('compiler')" :key="item.id" :value="item.id">{{ item.label }}</option></select><p>{{ descriptor('compiler', draft.compiler)?.description }}</p></article><i>→</i><article><header><b>3. Maker</b><span>代码生成</span></header><select :value="draft.maker" @change="updateStage('maker', ($event.target as HTMLSelectElement).value)"><option v-for="item in stage('maker')" :key="item.id" :value="item.id">{{ item.label }}</option></select><p>{{ descriptor('maker', draft.maker)?.description }}</p></article><i>→</i><article><header><b>4. Checkers</b><span>至少一项</span></header><label v-for="item in stage('checker')" :key="item.id" class="checker-option"><input type="checkbox" :checked="draft.checkers.includes(item.id)" @change="toggleChecker(item.id)" />{{ item.label }}</label><div class="selected-checkers"><span v-for="item in selectedCheckers" :key="item.id">{{ item.label }} <button @click="moveChecker(item.id, -1)">↑</button><button @click="moveChecker(item.id, 1)">↓</button></span></div></article><i>→</i><article><header><b>5. Delivery</b><span>制品去向</span></header><select :value="draft.delivery" @change="updateStage('delivery', ($event.target as HTMLSelectElement).value)"><option v-for="item in stage('delivery')" :key="item.id" :value="item.id">{{ item.label }}</option></select><p>{{ descriptor('delivery', draft.delivery)?.description }}</p></article></section><section class="composer-grid"><article class="workspace-panel"><div class="panel-heading"><div><h2>权限与预算</h2><span>草稿显式声明，不自动补全</span></div></div><div class="policy-grid"><label><input v-model="draft.policy.allow_network" type="checkbox" />网络</label><label><input v-model="draft.policy.allow_model" type="checkbox" />模型</label><label><input v-model="draft.policy.allow_git" type="checkbox" />Git</label><label><input v-model="draft.policy.allow_ssh" type="checkbox" />SSH</label><label><input v-model="draft.policy.allow_publish" type="checkbox" />发布</label><label><input v-model="draft.policy.allow_deploy" type="checkbox" />部署</label></div><div class="number-grid"><label>最大尝试<input v-model.number="draft.policy.max_attempts" type="number" min="1" /></label><label>超时（秒）<input v-model.number="draft.policy.timeout_seconds" type="number" min="0" /></label><label>成本上限（元）<input v-model.number="draft.policy.cost_limit_yuan" type="number" min="0" /></label><label>不可用处理<select v-model="draft.policy.on_unavailable"><option value="block">block</option><option value="review_required">review_required</option><option value="continue">continue</option></select></label></div><template v-if="draft.source.name === 'local_queue'"><p class="config-note">Source 配置只接受相对的队列/状态文件路径；不允许凭据字段。</p><div class="number-grid"><label>backlog_path<input v-model="draft.source.config.backlog_path" placeholder="可选，例如 data/backlog.json" /></label><label>state_path<input v-model="draft.source.config.state_path" placeholder="可选，例如 data/state.json" /></label></div></template><template v-if="draft.delivery === 'github_workflow'"><p class="data-warning">GitHub Workflow 是高副作用组合：这里只是草稿预检，不会读取凭据、推送或部署。</p><div class="number-grid"><label>仓库<input v-model="draft.delivery_config.repo" /></label><label>分支<input v-model="draft.delivery_config.branch" /></label><label>前缀<input v-model="draft.delivery_config.prefix" /></label><label>端口基数<input v-model.number="draft.delivery_config.port_base" type="number" min="1" /></label></div></template></article><article class="workspace-panel"><div class="panel-heading"><div><h2>组件风险摘要</h2><span>来自服务端白名单目录</span></div></div><div class="risk-list"><div v-for="item in [descriptor('source', draft.source.name),descriptor('compiler', draft.compiler),descriptor('maker', draft.maker),...selectedCheckers,descriptor('delivery', draft.delivery)]" :key="item?.id"><b>{{ item?.label }}</b><span :class="{ risk: risks(item) !== '离线本地' }">{{ risks(item) }}</span></div></div><button class="primary-button" :disabled="checking" @click="preflight">{{ checking ? '正在预检…' : '预检 Profile 草稿' }}</button><RouterLink class="quiet-button" to="/profile-composer/save">保存并加入 Profile 库</RouterLink><button class="quiet-button" @click="resetDraft">重置为安全本地草稿</button></article></section><section v-if="result" class="composer-grid result"><article class="workspace-panel"><div class="panel-heading"><div><h2>{{ result.valid ? '预检通过' : '预检未通过' }}</h2><span>执行：{{ result.execution.performed ? '是' : '否' }} · 写入：{{ result.execution.writes ? '是' : '否' }} · 网络：{{ result.execution.network ? '是' : '否' }}</span></div></div><p v-if="!result.diagnostics.length" class="saved">✓ 该草稿满足当前 Composer 的纯规则校验。</p><ul class="diagnostics"><li v-for="item in result.diagnostics" :key="`${item.path}-${item.code}`" :class="item.severity"><code>{{ item.path }}</code> {{ item.message }}</li></ul></article><article class="workspace-panel"><h2>完整 Profile JSON（未保存）</h2><pre>{{ JSON.stringify(result.normalized_profile || draft, null, 2) }}</pre></article></section><section class="workspace-panel safeguards"><h2>边界</h2><ul><li v-for="item in catalog.safeguards" :key="item">{{ item }}</li></ul></section></template></section></template>
<style scoped>.composer-meta,.composer-grid{display:grid;grid-template-columns:1fr 130px;gap:12px}.composer-meta label,.policy-grid label,.number-grid label{display:grid;gap:6px;color:var(--muted);font-size:11px}.composer-meta .wide{grid-column:1/-1}.composer input,.composer textarea,.composer select{width:100%;border:1px solid var(--line);border-radius:8px;background:var(--panel-2);padding:9px;color:var(--ink);font:inherit}.composer-flow{display:flex;align-items:flex-start;gap:8px;margin:14px 0;overflow:auto}.composer-flow article{min-width:180px;flex:1;padding:15px;border:1px solid var(--line);border-radius:12px;background:color-mix(in srgb,var(--panel) 88%,transparent)}.composer-flow i{align-self:center;color:var(--blue)}.composer-flow header b,.composer-flow header span{display:block}.composer-flow header span,.composer-flow p{color:var(--soft);font-size:10px}.composer-flow p{min-height:32px}.checker-option{display:block;margin:7px 0;color:var(--muted);font-size:11px}.selected-checkers{display:flex;gap:4px;flex-wrap:wrap}.selected-checkers span{padding:3px 5px;border-radius:5px;background:var(--panel-2);font-size:10px}.selected-checkers button{border:0;background:transparent;color:var(--blue);cursor:pointer}.composer-grid{grid-template-columns:1.2fr .8fr}.policy-grid{display:flex;flex-wrap:wrap;gap:8px 14px}.policy-grid label{display:flex;align-items:center;gap:5px}.policy-grid input{width:auto}.number-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:14px}.risk-list>div{display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-top:1px solid var(--line-soft);font-size:11px}.risk-list span{color:var(--mint)}.risk-list .risk{color:var(--amber)}.risk-list+button{margin-top:16px}.quiet-button{margin:9px 0 0 8px}.result{margin-top:14px}.diagnostics{padding-left:18px;font-size:12px}.diagnostics .error{color:var(--red)}.diagnostics .warning{color:var(--amber)}pre{max-height:420px;overflow:auto;margin:0;padding:12px;border-radius:8px;background:var(--panel-2);font-size:11px}.safeguards{margin-top:14px}.safeguards ul{margin-bottom:0;color:var(--muted);font-size:12px}@media(max-width:760px){.composer-meta,.composer-grid,.number-grid{grid-template-columns:1fr}.quiet-button{margin-left:0}}</style>
